# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">TAİF\'TE İSLAM\'IN YERLEŞMESİ VE İDARİ DÜZENLEMELER (HİCRİ 9 / 630)</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.2" font-weight="bold" fill="#1e40af">İDARİ, DİNÎ VE EĞİTİMSEL ADIMLAR</text>\n  <text x="34" y="88" font-size="10.8" font-weight="bold" fill="#1d4ed8">• Osman b. Ebü\'l-Âs\'ın Vali Atanması:</text>\n  <text x="44" y="104" font-size="10.4" fill="#1e3a8a">Sakîf Heyeti içinde Kur\'an ve fıkıh öğrenmeye en</text>\n  <text x="44" y="120" font-size="10.4" fill="#1e3a8a">gayretli genç sahabi Taif\'e vali ve imam tayin edildi.</text>\n  <text x="34" y="142" font-size="10.8" font-weight="bold" fill="#1d4ed8">• Lât Putunun Yıkılması:</text>\n  <text x="44" y="158" font-size="10.4" fill="#1e3a8a">Ebû Süfyân b. Harb ve Muğîre b. Şu\'be eliyle Lât</text>\n  <text x="44" y="174" font-size="10.4" fill="#1e3a8a">putu yıkılarak Taif\'te tevhit inancı hâkim kılındı.</text>\n  <text x="34" y="196" font-size="10.8" fill="#1e3a8a">• Taif Mescidi inşa edilerek Kur\'an eğitimi başlatıldı.</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.2" font-weight="bold" fill="#166534">TAİF\'İN İSLAMLAŞMASININ SONUÇLARI</text>\n  <text x="370" y="88" font-size="10.8" fill="#14532d">• Hicaz bölgesinde (Mekke - Medine - Taif üçgeninde)</text>\n  <text x="380" y="104" font-size="10.4" fill="#14532d">siyasi, dinî ve ticari birlik tamamlandı.</text>\n  <text x="370" y="126" font-size="10.8" fill="#14532d">• Müşriklerin Arap Yarımadası\'ndaki son büyük</text>\n  <text x="380" y="142" font-size="10.4" fill="#14532d">dayanağı barış yoluyla İslam\'a kazandı.</text>\n  <text x="370" y="164" font-size="10.8" font-weight="bold" fill="#15803d">• İslam\'da Sebat ve Sadakat:</text>\n  <text x="380" y="180" font-size="10.4" fill="#14532d">Hz. Ebû Bekir dönemindeki ridde (irtidat) olaylarında</text>\n  <text x="380" y="196" font-size="10.4" fill="#14532d">Taif halkı Osman b. Ebü\'l-Âs öncülüğünde sadık kaldı.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Taif\'in İslamlaşması kılıç zoruyla değil, Hz. Peygamber\'in (sav) duası, sabrı ve hikmetli siyasetiyle gerçekleşmiştir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">HZ. PEYGAMBER\'İN (SAV) TAİF SÜRECİNDEKİ NEBEVİ METODU (620 - 630)</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.2" font-weight="bold" fill="#854d0e">SONSUZ MERHAMET, AF VE HİDAYET DUASI</text>\n  <text x="34" y="88" font-size="10.6" fill="#713f12">• <tspan font-weight="bold">620 Taif Yolculuğu:</tspan> Taşlanmasına rağmen helak</text>\n  <text x="44" y="104" font-size="10.4" fill="#713f12">teklifini reddedip gelecek nesillerin imanını diledi.</text>\n  <text x="34" y="126" font-size="10.6" fill="#713f12">• <tspan font-weight="bold">630 Taif Kuşatması:</tspan> Beddua yerine «Allah\'ım!</text>\n  <text x="44" y="142" font-size="10.4" fill="#713f12">Sakîf\'e hidayet ver ve onları bize getir!» buyurdu.</text>\n  <text x="34" y="164" font-size="10.6" fill="#713f12">• <tspan font-weight="bold">Mescid-i Nebevî\'de İkram:</tspan> Kendisini taşlatan</text>\n  <text x="44" y="180" font-size="10.4" fill="#713f12">Abdiyâlîl ve heyetini mescidde ağırlayıp Kur\'an dinletti.</text>\n  <text x="34" y="202" font-size="10.5" font-weight="bold" fill="#a16207">• Geçmişteki eziyetlerin intikamını almaktan kaçındı.</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.2" font-weight="bold" fill="#6b21a8">TEVHİT VE İBADETTE TAVİZSİZ İLKELİ DURUŞ</text>\n  <text x="370" y="88" font-size="10.6" font-weight="bold" fill="#7e22ce">• Tevhit İlkesi (Lât Putunun Reddi):</text>\n  <text x="380" y="104" font-size="10.4" fill="#581c87">Lât putunun 3 yıl veya 1 ay bile kalması talebini</text>\n  <text x="380" y="120" font-size="10.4" fill="#581c87">reddetti; ancak kendi elleriyle yıkmama isteğini</text>\n  <text x="380" y="136" font-size="10.4" fill="#581c87">gözeterek yıkım için sahabileri görevlendirdi.</text>\n  <text x="370" y="158" font-size="10.6" font-weight="bold" fill="#7e22ce">• İbadet İlkesi (Namazın Farziyeti):</text>\n  <text x="380" y="174" font-size="10.4" fill="#581c87">Namazdan muafiyet isteğini «Namazsız (rükûsuz)</text>\n  <text x="380" y="190" font-size="10.4" fill="#581c87">bir dinde hayır yoktur!» buyurarak geri çevirdi.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Nebevi Yöntem: İnsanlara karşı merhamet ve kolaylık, inanç ve ibadet esaslarında ise tam kararlılık.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">1. ÜNİTE ÖZETİ: TAİF\'İN İSLAMLAŞMA SÜRECİ KRONOLOJİSİ</text>\n  <rect x="18" y="44" width="158" height="168" rx="8" fill="#dbeafe" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="97" y="64" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">1. HÜZÜN YILI (619-620)</text>\n  <text x="28" y="86" font-size="10" fill="#1e3a8a">• Ebû Tâlib ve Hz. Hatice\'nin</text>\n  <text x="34" y="100" font-size="10" fill="#1e3a8a">vefatı üzerine Mekke\'de</text>\n  <text x="34" y="114" font-size="10" fill="#1e3a8a">himayenin kalkması.</text>\n  <text x="28" y="134" font-size="10" fill="#1e3a8a">• Zeyd b. Hârise ile birlikte</text>\n  <text x="34" y="148" font-size="10" fill="#1e3a8a">yeni bir davet merkezi</text>\n  <text x="34" y="162" font-size="10" fill="#1e3a8a">için Taif\'e gidilmesi.</text>\n  <rect x="186" y="44" width="158" height="168" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="265" y="64" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">2. TAİF YOLCULUĞU (620)</text>\n  <text x="196" y="86" font-size="10" fill="#78350f">• Sakîf liderlerinin reddi</text>\n  <text x="202" y="100" font-size="10" fill="#78350f">ve taşlı saldırı.</text>\n  <text x="196" y="120" font-size="10" fill="#78350f">• Bağda Ninovalı Addâs\'ın</text>\n  <text x="202" y="134" font-size="10" fill="#78350f">Müslüman olması.</text>\n  <text x="196" y="154" font-size="10" fill="#78350f">• Dağlar Meleği\'ne af cevabı.</text>\n  <text x="196" y="174" font-size="10" fill="#78350f">• Mut\'im b. Adî\'nin emanı</text>\n  <text x="202" y="188" font-size="10" fill="#78350f">ile Mekke\'ye dönüş.</text>\n  <rect x="354" y="44" width="158" height="168" rx="8" fill="#ffedd5" stroke="#ea580c" stroke-width="1.8"/>\n  <text x="433" y="64" text-anchor="middle" font-size="11" font-weight="bold" fill="#9a3412">3. KUŞATMA (630 / H. 8)</text>\n  <text x="364" y="86" font-size="10" fill="#7c2d12">• Mekke\'nin Fethi ve Huneyn</text>\n  <text x="370" y="100" font-size="10" fill="#7c2d12">Gazvesi sonrası kuşatma.</text>\n  <text x="364" y="120" font-size="10" fill="#7c2d12">• Kuşatmanın kaldırılması ve</text>\n  <text x="370" y="134" font-size="10" fill="#7c2d12">Sakîf için hidayet duası.</text>\n  <text x="364" y="154" font-size="10" fill="#7c2d12">• Mâlik b. Avf\'ın İslam\'a</text>\n  <text x="370" y="168" font-size="10" fill="#7c2d12">girmesi; Urve b. Mes\'ûd\'un</text>\n  <text x="370" y="182" font-size="10" fill="#7c2d12">Taif\'te şehit edilmesi.</text>\n  <rect x="522" y="44" width="160" height="168" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="602" y="64" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">4. İSLAMLAŞMA (630 / H. 9)</text>\n  <text x="532" y="86" font-size="10" fill="#14532d">• Abdiyâlîl başkanlığındaki</text>\n  <text x="538" y="100" font-size="10" fill="#14532d">Sakîf Heyeti\'nin Medine\'de</text>\n  <text x="538" y="114" font-size="10" fill="#14532d">Müslüman olması.</text>\n  <text x="532" y="134" font-size="10" fill="#14532d">• Lât putunun yıkılması.</text>\n  <text x="532" y="154" font-size="10" fill="#14532d">• Osman b. Ebü\'l-Âs\'ın</text>\n  <text x="538" y="168" font-size="10" fill="#14532d">vali tayin edilmesi ve</text>\n  <text x="538" y="182" font-size="10" fill="#14532d">Taif\'in İslam\'da sebatı.</text>\n  <rect x="18" y="222" width="664" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="239" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">620 yılında taşlarla karşılanan İslam daveti, 630 yılında gönülleri fethederek Taif\'i İslam\'ın kalesi yapmıştır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
